WITH SSBCI AS (

SELECT DISTINCT CASE WHEN MBR_ID LIKE '%|%' THEN SPLIT_PART(MBR_ID,'|',1) ELSE SUBSTR(MBR_ID,1,10) END AS MBR_ID, CASE WHEN MAX(QUALIFIED) = 1 THEN 'YES' ELSE 'NO' END AS SSBCI_FLAG FROM QSF20_CMIDB001.CMI.SSBCI_MEMBER_LIST GROUP BY CASE WHEN MBR_ID LIKE '%|%' THEN SPLIT_PART(MBR_ID,'|',1) ELSE SUBSTR(MBR_ID,1,10) END)
SELECT DISTINCT
'CA5' AS Health_Plan_Code
,CASE WHEN BEN_PLN.BENFT_PLN_ID in ('A0061MASWMNP01','A0061MASWMNP02','A0061MASWMNP03','A0061MASWMNP04','A0061MASWMNP05','A0061MASWMNP06','A0061MASWMNP07','A0061MASWNEP08','A0061MASWNEP09','A0061MASWSDP10','A0061MASWSDP11','A0061MASWSDP12','A0061MASWNEP13','A0061MASWMNS01','A0061MASWSDP15','A0061MASWSDP16') THEN 'PCA5-4911' WHEN BEN_PLN.BENFT_PLN_ID IN ('A0061MASWNDP14') THEN 'PCA5-5240' WHEN BEN_PLN.BENFT_PLN_ID IN ('C01475_0001','C01475_0002','C01475_0004','C01475_0005','C01475_0010') THEN 'PCA5-5242' ELSE 'PCA5-4913' END AS Program_Code
,SUBSTR(MFV.SBSCR_ID,1,10) AS MBR_ID
,CASE WHEN MFV.EFCTV_DT < '2025-01-01 00:00:00.000' THEN '01/01/2025' ELSE TO_CHAR(MFV.EFCTV_DT,'MM/DD/YYYY') END  AS EFCTV_DT
,TO_CHAR(MFV.EXPIR_DT,'MM/DD/YYYY') AS EXPIR_DT
,BEN_PLN.BENFT_PLN_ID AS CLIENT_KEY_ID
--,S.SSBCI_FLAG AS SSBCI_FLAG
FROM DFDS.DFDS_MBR_FULL_VU MFV
INNER JOIN BASE_DS.BASE_DS_BENFT_PLN_CORE_VU BEN_PLN ON MFV.BENFT_PLN_KEY=BEN_PLN.BENFT_PLN_KEY
JOIN CIM.BENFT_PLN_EFCTV BPEF ON BPEF.BENFT_PLN_KEY = MFV.BENFT_PLN_KEY 
AND (to_varchar('1/1/2025') BETWEEN BPEF.EFCTV_DT and BPEF.EXPIR_DT OR CURRENT_DATE BETWEEN BPEF.EFCTV_DT and BPEF.EXPIR_DT OR to_varchar('1/1/2026') BETWEEN BPEF.EFCTV_DT and BPEF.EXPIR_DT) AND BPEF.ACTV_INDC = 1 LEFT JOIN SSBCI S ON SUBSTR(MFV.SBSCR_ID,1,10) = S.MBR_ID AND Program_Code = 'PCA5-5240' 
WHERE 1=1
AND BEN_PLN.BENFT_PLN_ID in ('A0061MASWNDP14','A0061MASWMNP01','A0061MASWMNP02','A0061MASWMNP03','A0061MASWMNP04','A0061MASWMNP05','A0061MASWMNP06','A0061MASWMNP07','A0061MASWNEP08','A0061MASWNEP09','A0061MASWSDP10','A0061MASWSDP11','A0061MASWSDP12','A0061MASWNEP13','A0061MASWMNS01','A0061MGASWMNP05','A0061MGASWMNP02','A0061MGASWMNP12','A0061MASWSDP15','A0061MASWSDP16','C01475_0001','C01475_0002','C01475_0004','C01475_0005','C01475_0010')
AND BEN_PLN.REC_SRC_CD IN ('HR2','CONVEY','HRCATE') AND YEAR(MFV.BENFT_PLN_EFCTV_EXPIR_DT)>2023 AND MFV.EFCTV_DT >= '1/1/2025' AND MFV.EFCTV_DT < MFV.EXPIR_DT AND MFV.EFCTV_DT <= CURRENT_DATE+30 AND MFV.EXPIR_DT > CURRENT_DATE
AND(((BPEF.EXPIR_DT >=ADD_MONTHS(TO_DATE(to_varchar(CURRENT_DATE,'MM/DD/YYYY'),'MM/DD/YYYY'),0) AND BPEF.EFCTV_DT <= to_varchar(CURRENT_DATE,'MM/DD/YYYY')) OR BPEF.EFCTV_DT = ADD_MONTHS(TO_DATE(to_varchar(CURRENT_DATE,'MM/DD/YYYY'),'MM/DD/YYYY'),1) OR BPEF.EFCTV_DT BETWEEN CURRENT_DATE AND (to_varchar(CURRENT_DATE+1*30, 'MM/DD/YYYY'))) OR to_varchar(CURRENT_DATE,'MM/DD/YYYY') BETWEEN BPEF.EFCTV_DT AND BPEF.EXPIR_DT)
 
UNION ALL
 
SELECT DISTINCT
'CA5' AS Health_Plan_Code
,CASE WHEN MFV.GRP_NBR IN (07592, 07800, 07850, 07854, 07860, 07864, 07874, 07876, 07879, 07881, 07884, 07885, 07886, 07887, 07888, 07889) THEN 'PCA5-5240' ELSE 'PCA5-4913' END AS Program_Code
,CASE WHEN MFV.MOI_ALTID_ALT_ID_OTHR_INFO_1 IS NOT NULL THEN SUBSTR(MFV.MOI_ALTID_ALT_ID_OTHR_INFO_1,1,9) ELSE SUBSTR(MFV.SBSCR_ID,1,9) END  AS MBR_ID
,CASE WHEN MFV.EFCTV_DT < '2025-01-01 00:00:00.000' THEN '01/01/2025' ELSE TO_CHAR(MFV.EFCTV_DT,'MM/DD/YYYY') END AS EFCTV_DT
,TO_CHAR(MFV.EXPIR_DT,'MM/DD/YYYY') AS EXPIR_DT
,CASE WHEN MFV.GRP_NBR IN (70101, 70109, 70123, 70138, 70150, 70151, 70153, 70162, 70165, 70179, 70180, 70181, 70183, 70184, 70192,  70196, 70503, 70508, 70511, 70514, 70516, 70519, 70522, 70524, 70525, 70530, 70531, 70535, 70536, 70538, 70552, 70590, 70591, 70603, 70604, 70609, 70612,  70620, 70632, 70635, 70636, 70661,70678, 70684, 70692, 70801, 70818, 70854, 70873, 70876) THEN 'EGHPCOST02' WHEN MFV.GRP_NBR IN (70007,  70127, 70152, 70164, 70166, 70169, 70173,  70178, 70185, 70186, 70188, 70189, 70193, 70197, 70198, 70533, 70542, 70628, 70640, 70668, 70701,70702, 70819,70589,70625,70703, 70705, 70711, 70713, 70715) THEN 'EGHPCOST05' WHEN MFV.GRP_NBR IN (70191) THEN 'EGHPCOST12' WHEN MFV.GRP_NBR IN (07592, 07800, 07850, 07854, 07860, 07864, 07874, 07876, 07879, 07881, 07884, 07885, 07886, 07887, 07888, 07889) THEN 'MAPDMSHO' END AS CLIENT_KEY_ID
--,S.SSBCI_FLAG AS SSBCI_FLAG
FROM DFDS.DFDS_MBR_FULL_VU MFV
INNER JOIN BASE_DS.BASE_DS_BENFT_PLN_CORE_VU BEN_PLN ON MFV.BENFT_PLN_KEY=BEN_PLN.BENFT_PLN_KEY
JOIN CIM.GRP_EFCTV GEF ON GEF.GRP_EFCTV_KEY = MFV.GRP_EFCTV_KEY AND GEF.ACTV_INDC = 1 AND GEF.EFCTV_DT < GEF.EXPIR_DT LEFT JOIN SSBCI S ON CASE WHEN MFV.MOI_ALTID_ALT_ID_OTHR_INFO_1 IS NOT NULL THEN SUBSTR(MFV.MOI_ALTID_ALT_ID_OTHR_INFO_1,1,9) ELSE SUBSTR(MFV.SBSCR_ID,1,9) END = S.MBR_ID AND Program_Code = 'PCA5-5240'
WHERE 1=1
AND MFV.GRP_NBR IN (70007,70127,70152, 70164, 70166, 70169, 70173, 70668,70178, 70185,70186, 70188, 70189, 70191, 70193, 70197, 70198,70533, 70542, 70628, 70640,70701,70819,70101, 70109, 70123, 70138, 70150, 70151, 70153, 70162, 70165, 70179, 70180, 70181, 70183, 70184, 70192, 70196, 70503, 70508, 70511, 70514, 70516, 70519, 70522, 70524, 70525, 70530, 70531, 70535, 70536, 70538, 70552, 70590, 70591, 70603, 70604, 70609, 70612, 70620, 70632, 70635, 70636, 70661,70678, 70684, 70692, 70801, 70818, 70854, 70873, 70876,70702,07592, 07800, 07850, 07854, 07860, 07864, 07874, 07876, 07879, 07881, 07884, 07885, 07886, 07887, 07888, 07889,70589,70625,70703, 70705, 70711, 70713, 70715)
AND MFV.REC_SRC_CD IN ('COSMOS') AND YEAR(MFV.GRP_EFCTV_EXPIR_DT)>2023 AND MFV.EFCTV_DT >= '1/1/2025' AND MFV.EFCTV_DT < MFV.EXPIR_DT AND MFV.EFCTV_DT <= to_varchar(CURRENT_DATE+30, 'MM/DD/YYYY') AND MFV.EXPIR_DT > CURRENT_DATE 
AND(((MFV.GRP_EFCTV_EXPIR_DT >=ADD_MONTHS(TO_DATE(to_varchar(CURRENT_DATE,'MM/DD/YYYY'),'MM/DD/YYYY'),0) AND MFV.GRP_EFCTV_EFCTV_DT <= to_varchar(CURRENT_DATE,'MM/DD/YYYY')) OR MFV.GRP_EFCTV_EFCTV_DT = ADD_MONTHS(TO_DATE(to_varchar(CURRENT_DATE,'MM/DD/YYYY'),'MM/DD/YYYY'),1) OR MFV.GRP_EFCTV_EFCTV_DT BETWEEN CURRENT_DATE AND (to_varchar(CURRENT_DATE+1*30, 'MM/DD/YYYY'))) OR to_varchar(CURRENT_DATE,'MM/DD/YYYY') BETWEEN MFV.GRP_EFCTV_EFCTV_DT AND MFV.GRP_EFCTV_EXPIR_DT) ORDER BY MBR_ID,to_date(EFCTV_DT),CLIENT_KEY_ID,EXPIR_DT